const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');function close(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();menu.focus()}});nav.addEventListener('click',e=>{if(e.target.closest('a'))close()});